mapper.select:
SELECT result.type, result.id, result.title, result.description FROM ( SELECT 'farmTask' AS type, ft.id AS id, ft.task_title AS title, CONCAT('农事任务 · ', COALESCE(p.plot_name, '未关联地块')) AS description, 1 AS type_order FROM `farm_task` ft LEFT JOIN `plot` p ON p.id = ft.plot_id WHERE (ft.task_title LIKE CONCAT('%', #{keyword}, '%') OR ft.task_content LIKE CONCAT('%', #{keyword}, '%'))
AND ft.user_id = #{userId}
UNION ALL
SELECT 'iotDevice' AS type, d.id AS id, d.name AS title, CONCAT('设备 · ', d.device_code, ' · ', COALESCE(p.plot_name, '未关联地块')) AS description, 2 AS type_order FROM `iot_device` d LEFT JOIN `plot` p ON p.id = d.plot_id WHERE (d.name LIKE CONCAT('%', #{keyword}, '%') OR d.device_code LIKE CONCAT('%', #{keyword}, '%'))
AND d.user_id = #{userId}
UNION ALL
SELECT 'plot' AS type, p.id AS id, p.plot_name AS title, CONCAT('地块 · ', COALESCE(p.plot_code, '暂无编号')) AS description, 3 AS type_order FROM `plot` p WHERE (p.plot_name LIKE CONCAT('%', #{keyword}, '%') OR p.plot_code LIKE CONCAT('%', #{keyword}, '%'))
AND p.user_id = #{userId}
) result ORDER BY result.type_order, result.id DESC LIMIT #{limit}
